dashboard.definition:
{
  "title": "Explore",
  "description": "Find an asset by any key value and see which source supplied each piece of its information.",
  "visualizations": {
    "viz_help": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "**Find an asset** by any key value (IP address, MAC address, host name, user name ...). Matching is lowercase; MAC addresses, short host names and the user part of `DOMAIN\\user` / `user@domain` are tried too, and keys that are scoped need the scope. **Select a row** to see which source supplied each piece of its information.\n\n*Source rows are not available yet: The merge search has no key fields to trace; add at least one key field.*",
        "fontSize": "default"
      }
    },
    "viz_assets": {
      "type": "splunk.table",
      "title": "Matching assets (select one)",
      "dataSources": {
        "primary": "ds_assets"
      },
      "options": {
        "count": 10,
        "dataOverlayMode": "none",
        "showRowNumbers": false
      },
      "eventHandlers": [
        {
          "type": "drilldown.setToken",
          "options": {
            "tokens": [
              {
                "token": "adb_keys",
                "key": "row.adb_keys.value"
              }
            ]
          }
        }
      ]
    },
    "viz_sources": {
      "type": "splunk.table",
      "title": "Source data behind the selected asset",
      "description": "Every source row that carries one of the asset's keys, as the merge sees it (after column mapping, normalizing, ignore lists and filters).",
      "dataSources": {
        "primary": "ds_sources"
      },
      "options": {
        "count": 20,
        "dataOverlayMode": "none",
        "showRowNumbers": false
      }
    }
  },
  "dataSources": {
    "ds_assets": {
      "type": "ds.search",
      "name": "Matching assets",
      "options": {
        "query": "| makeresults\n| eval q=lower(trim($adb_term|s$)), sc=lower(trim($adb_scope|s$))\n| where len(q) > 0\n| eval c=mvappend(q, if(match(q, \"^[0-9a-f]{2}([^0-9a-f]?[0-9a-f]{2}){5}$$\"), replace(replace(q, \"[^0-9a-f]\", \"\"), \"(..)(?=.)\", \"\\\\1:\"), null()), if(match(q, \"\\\\.\") AND NOT match(q, \"^\\\\d+(\\\\.\\\\d+){3}$$\"), mvindex(split(q, \".\"), 0), null()), if(match(q, \"\\\\\\\\\"), replace(q, \"^.*\\\\\\\\\", \"\"), null()), if(match(q, \"@\"), mvindex(split(q, \"@\"), 0), null()))\n| mvexpand c\n| eval c=if(len(sc) > 0, sc . \"|\" . c, c)\n| lookup assetdb asset AS c OUTPUTNEW `adb_enrich_outputs`\n| where isnotnull(asset_id)\n| dedup asset_id\n| lookup assetdb _key AS asset_id OUTPUT asset AS adb_keys_mv\n| eval adb_keys=mvjoin(adb_keys_mv, \"|\"), last_seen=strftime(asset_last_seen, \"%F %T\")\n| table adb_keys, asset_source, last_seen",
        "queryParameters": {
          "earliest": "-1m",
          "latest": "now"
        }
      }
    },
    "ds_sources": {
      "type": "ds.search",
      "name": "Source rows",
      "options": {
        "query": "| makeresults | where 1=0 | eval source=\"\", note=\"\"",
        "queryParameters": {
          "earliest": "-1m",
          "latest": "now"
        }
      }
    }
  },
  "inputs": {
    "input_term": {
      "type": "input.text",
      "title": "Key value",
      "options": {
        "defaultValue": " ",
        "token": "adb_term"
      }
    },
    "input_scope": {
      "type": "input.text",
      "title": "Scope (optional)",
      "options": {
        "defaultValue": " ",
        "token": "adb_scope"
      }
    }
  },
  "layout": {
    "type": "grid",
    "options": {
      "width": 1440,
      "height": 1100
    },
    "structure": [
      {
        "item": "viz_help",
        "type": "block",
        "position": {
          "x": 0,
          "y": 0,
          "w": 1440,
          "h": 110
        }
      },
      {
        "item": "viz_assets",
        "type": "block",
        "position": {
          "x": 0,
          "y": 110,
          "w": 1440,
          "h": 380
        }
      },
      {
        "item": "viz_sources",
        "type": "block",
        "position": {
          "x": 0,
          "y": 490,
          "w": 1440,
          "h": 560
        }
      }
    ],
    "globalInputs": [
      "input_term",
      "input_scope"
    ]
  }
}
